@inline function ratt2_kernel_lane(i,N,T,RF,RB,EG,TCONV)
 FT=eltype(T)
 @inbounds begin
 TEMP = T[i]*TCONV
 SMALL_INV = FT(1e37)
 RU = FT(8.31451e7)
 PATM = FT(1.01325e6)
 PFAC = s3d_div(PATM, (RU*(TEMP)))
 rtemp_inv = s3d_div((EG[(2-1)*N+i]*EG[(4-1)*N+i]), (EG[(3-1)*N+i]*EG[(5-1)*N+i]))
 RB[(1-1)*N+i] = RF[(1-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(1-1)*N+i]*EG[(3-1)*N+i]), (EG[(2-1)*N+i]*EG[(5-1)*N+i]))
 RB[(2-1)*N+i] = RF[(2-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(1-1)*N+i]*EG[(5-1)*N+i]), (EG[(2-1)*N+i]*EG[(6-1)*N+i]))
 RB[(3-1)*N+i] = RF[(3-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(5-1)*N+i]*EG[(5-1)*N+i]), (EG[(3-1)*N+i]*EG[(6-1)*N+i]))
 RB[(4-1)*N+i] = RF[(4-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(2-1)*N+i]*EG[(2-1)*N+i]*PFAC), EG[(1-1)*N+i])
 RB[(5-1)*N+i] = RF[(5-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(2-1)*N+i]*EG[(2-1)*N+i]*PFAC), EG[(1-1)*N+i])
 RB[(6-1)*N+i] = RF[(6-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(2-1)*N+i]*EG[(2-1)*N+i]*PFAC), EG[(1-1)*N+i])
 RB[(7-1)*N+i] = RF[(7-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(2-1)*N+i]*EG[(2-1)*N+i]*PFAC), EG[(1-1)*N+i])
 RB[(8-1)*N+i] = RF[(8-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(2-1)*N+i]*EG[(5-1)*N+i]*PFAC), EG[(6-1)*N+i])
 RB[(9-1)*N+i] = RF[(9-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(2-1)*N+i]*EG[(3-1)*N+i]*PFAC), EG[(5-1)*N+i])
 RB[(10-1)*N+i] = RF[(10-1)*N+i] * min(rtemp_inv, SMALL_INV)
 rtemp_inv = s3d_div((EG[(3-1)*N+i]*EG[(3-1)*N+i]*PFAC), EG[(4-1)*N+i])
 RB[(11-1)*N+i] = RF[(11-1)*N+i] * min(rtemp_inv, SMALL_INV)
